.shot-result>button{height:38px;margin-top:9px;border-radius:10px;background:linear-gradient(90deg,#6749ff,#9069ff);font-weight:800;box-shadow:0 7px 16px #7657ff28}.shot-result>button:not(:disabled):hover{filter:brightness(1.06)}.shot-result>small{margin-top:7px;font-size:9px}
